# Initially generated by GitHub Copilot.
"""Shared סוג mapping and reconciliation for trivial ketiv/qere templates."""

from foi import kq_trivial_types as ktt
from pycmn import ws_tmpl2 as wtp

DISAGREE = "disagree"

SUG_STATUS_MATCH = "match"
SUG_STATUS_MISMATCH = "mismatch"
SUG_STATUS_UNRECOGNIZED = "unrecognized"

UNRECOGNIZED_SUG_CAT_PREFIX = "unrecognized:"


# Mapping reused by FOI reconciliation and ws bot add-type behavior.
SUG_TEXT_BY_SUBTYPE = {
    ktt.QYV: 'כתיב חסר יו"ד בסיומת של קמץ ואחריו וי"ו',
    ktt.EXTRA_ALEF: 'אל"ף מיותרת',
    ktt.HI_SPELLED_HU: "כתיב הוא קרי היא",
    ktt.N3RH_SPELLED_N3R: "כתיב נער קרי נערה",
    ktt.XOLAM_HE: 'כתיב ה"א בסיומת של חולם',
}

SUBTYPE_BY_SUG_TEXT = {text: subtype for subtype, text in SUG_TEXT_BY_SUBTYPE.items()}


def sug_text_for_subtype(subtype):
    return SUG_TEXT_BY_SUBTYPE.get(subtype)


def extract_sug_text(tmpl):
    """Return סוג text or None when absent/blank."""
    if "סוג" not in wtp.template_param_keys(tmpl):
        return None
    raw_text = _flatten_text(wtp.template_param_val(tmpl, "סוג")).strip()
    return raw_text or None


def sug_cat_for_text(sug_text):
    if sug_text is None:
        return ktt.MISC
    return SUBTYPE_BY_SUG_TEXT.get(sug_text) or _unrecognized_sug_cat(sug_text)


def reconcile_subtype_for_foi(tmpl):
    """Return (final_subtype, diagnostics) for FOI z-trivial pathing.

    diagnostics is empty on agreement. On disagreement, diagnostics includes:
    foi_cat, sug_cat, and sug_status.
    """
    classifier_subtype = ktt.subtype_for_path(tmpl)
    sug_text = extract_sug_text(tmpl)
    sug_cat = sug_cat_for_text(sug_text)
    sug_status = _sug_status(classifier_subtype, sug_cat)
    if sug_status == SUG_STATUS_MATCH:
        return classifier_subtype, {}
    return DISAGREE, {
        "foi_cat": classifier_subtype,
        "sug_cat": sug_cat,
        "sug_status": sug_status,
    }


def expected_classifier_subtype_for_foi_row(row_subtype, row):
    """Return classifier subtype encoded by an FOI z-trivial row."""
    if row_subtype != DISAGREE:
        return row_subtype
    foi_cat = row.get("foi_cat")
    assert foi_cat is not None, row
    return foi_cat


def _sug_status(classifier_subtype, sug_cat):
    if sug_cat.startswith(UNRECOGNIZED_SUG_CAT_PREFIX):
        return SUG_STATUS_UNRECOGNIZED
    if classifier_subtype == sug_cat:
        return SUG_STATUS_MATCH
    return SUG_STATUS_MISMATCH


def _unrecognized_sug_cat(sug_text):
    return UNRECOGNIZED_SUG_CAT_PREFIX + sug_text


def _flatten_text(wtel):
    if isinstance(wtel, str):
        return wtel
    if isinstance(wtel, list):
        return "".join(_flatten_text(item) for item in wtel)
    assert wtp.is_template(wtel), wtel
    return _flatten_text(wtp.template_element(wtel, 1))
